export function formatEuros(cents) {
  const euros = cents / 100;
  const sign = euros < 0 ? '-' : '';
  const abs = Math.abs(euros);
  const formatted = abs.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return `${sign}€${formatted}`;
}

